Customer Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(customer_portal, "Customer Portal") {
    Component(CustomerSPA, "Customer SPA", "React, TypeScript, Vite", "Renders the user interface and handles client-side routing and state for customers and brokers.")
    Component(StateAndQueryManager, "State and Query Manager", "TanStack Query, Zustand", "Manages lightweight client-side state and caches API responses.")
}

Rel(CustomerSPA, StateAndQueryManager, "Reads and writes application state and caches data", "")

@enduml

Web Frontend.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(web_frontend, "Web Frontend") {
    Component(Customer_Portal_UI, "Customer Portal UI", "React / TypeScript", "Provides the user interface for customers to interact with the claims system.")
    Component(Broker_Portal_UI, "Broker Portal UI", "React / TypeScript", "Provides the user interface for brokers managing claims on behalf of clients.")
    Component(Claims_Adjuster_Dashboard, "Claims Adjuster Dashboard", "React / TypeScript", "Provides the user interface for claims adjusters to process and review claims.")
}

System_Ext(API_Gateway_BFF, "API Gateway / BFF", "Node.js / Express backend-for-frontend")

Rel(Customer_Portal_UI, API_Gateway_BFF, "Sends API requests and WebSocket messages", "HTTPS/REST, WSS (JSON)")
Rel(Broker_Portal_UI, API_Gateway_BFF, "Sends API requests and WebSocket messages", "HTTPS/REST, WSS (JSON)")
Rel(Claims_Adjuster_Dashboard, API_Gateway_BFF, "Sends API requests and WebSocket messages", "HTTPS/REST, WSS (JSON)")

@enduml

Configuration & Feature Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Configuration & Feature Store container

Container_Boundary("Configuration_Feature_Store", "Configuration & Feature Store") {
    Component(Feature_Flag_Evaluator, "Feature Flag Evaluator", "Azure App Configuration SDK", "Evaluates dynamic feature toggles and rollout rules for the Claims Core Service and BFF.")
    Component(Secret_Manager_Client, "Secret Manager Client", "Azure Key Vault References", "Retrieves secure secrets and connection strings referenced by the configuration store.")
}

Rel(Feature_Flag_Evaluator, Secret_Manager_Client, "Resolves secure references", "HTTPS")

@enduml
